const input = $json || {};
const source = (input.body && typeof input.body === 'object') ? input.body : input;
const cfg = $item(0).$node['Config'].json || {};

function parseCsv(text) {
  const rows = [];
  let row = [];
  let cell = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const next = text[i + 1];
    if (inQuotes) {
      if (ch === '"' && next === '"') { cell += '"'; i++; }
      else if (ch === '"') inQuotes = false;
      else cell += ch;
    } else {
      if (ch === '"') inQuotes = true;
      else if (ch === ',') { row.push(cell); cell = ''; }
      else if (ch === '\n') { row.push(cell); rows.push(row); row = []; cell = ''; }
      else if (ch === '\r') {}
      else cell += ch;
    }
  }
  if (cell.length || row.length) { row.push(cell); rows.push(row); }
  return rows;
}

function rowsToObjects(rows) {
  if (!rows.length) return [];
  const headers = rows[0].map((h) => String(h || '').trim());
  const out = [];
  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    const obj = {};
    headers.forEach((h, idx) => { if (h) obj[h] = r[idx] ?? ''; });
    const hasAny = Object.values(obj).some((v) => String(v || '').trim() !== '');
    if (hasAny) out.push(obj);
  }
  return out;
}

function nk(s) {
  return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

function pick(obj, aliases) {
  const wanted = new Set((aliases || []).map(nk));
  for (const [k, v] of Object.entries(obj || {})) {
    if (wanted.has(nk(k)) && String(v ?? '').trim() !== '') return String(v).trim();
  }
  return '';
}

function stripCsvExt(v) {
  return String(v || '').trim().replace(/\.csv$/i, '');
}

function slugify(v) {
  return stripCsvExt(v).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

function parseTags(raw, defaultTag, sourceFileBase) {
  const initial = String(raw || '').trim();
  const tags = initial ? initial.split(',').map((t) => t.trim()).filter((t) => t) : [];
  if (defaultTag) tags.push(String(defaultTag).trim());
  if (sourceFileBase) tags.push(slugify(sourceFileBase));
  return tags.filter((t) => t).filter((v, i, a) => a.indexOf(v) === i);
}

function getArrayPayload(obj) {
  if (Array.isArray(obj)) return obj;
  if (Array.isArray(obj?.customFields)) return obj.customFields;
  if (Array.isArray(obj?.data?.customFields)) return obj.data.customFields;
  if (Array.isArray(obj?.data)) return obj.data;
  return [];
}

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

async function apiRequest({ method, baseUrl, path, headers, body }) {
  const options = {
    method,
    url: `${String(baseUrl).replace(/\/$/, '')}${path}`,
    headers,
    json: true,
  };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, status: 200, data };
  } catch (err) {
    return {
      ok: false,
      status: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500,
      data: err?.response?.body || err?.message || err,
      requestBody: body,
    };
  }
}

let records = [];
if (Array.isArray(source.records)) {
  records = source.records;
} else if (typeof source.csvText === 'string' && source.csvText.trim() !== '') {
  records = rowsToObjects(parseCsv(source.csvText));
}
if (!records.length) throw new Error('Provide body.records (array) or body.csvText (CSV string)');

const dryRun = (source.dryRun === undefined || source.dryRun === null) ? !!cfg.defaultDryRun : !!source.dryRun;
const locationId = String(source.locationId || cfg.locationId || '').trim();
const apiBaseUrl = String(source.apiBaseUrl || cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').trim();
const apiKey = String(source.apiKey || cfg.apiKey || '').trim();
const defaultTag = String(source.defaultTag || cfg.defaultTag || 'emerald').trim();
const sourceFileOverride = stripCsvExt(source.sourceFile || source.batchUpload || '');

if (!locationId) throw new Error('Missing locationId');
if (!dryRun && !apiKey) throw new Error('Missing apiKey (provide body.apiKey for live run)');

const authHeaders = {
  Authorization: `Bearer ${apiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

const customFieldSpecs = [
  { name: 'Title', aliases: ['Titles', 'Title', 'title'] },
  { name: 'Batch_Upload', aliases: ['source_file', 'sourceFile', 'Source File'], computed: 'sourceFile' },
  { name: 'Em_Emerald_Contact_ID', aliases: ['Emerald Contact ID', 'emerald_contact_id'] },
  { name: 'Em_Roles', aliases: ['Roles', 'roles'] },
  { name: 'Em_Seniorities', aliases: ['Seniorities', 'seniorities'] },
  { name: 'Em_All_Known_Emails', aliases: ['All Known Emails', 'all_known_emails'] },
  { name: 'Em_All_Known_Phones', aliases: ['All Known Phones', 'all_known_phones'] },
  { name: 'Em_Contact_LinkedIn_URLs', aliases: ['Contact LinkedIn URL(s)', 'contact_linkedin_urls'] },
  { name: 'Em_Contact_Non_LinkedIn_URLs', aliases: ['Contact non-LinkedIn URL(s)', 'contact_non_linkedin_urls'] },
  { name: 'Em_Emerald_Location_IDs', aliases: ['Emerald Location id(s)', 'emerald_location_ids'] },
  { name: 'Em_Location_Legal_Names', aliases: ['Location Legal Name(s)', 'location_legal_names'] },
  { name: 'Em_Location_Display_Names', aliases: ['Location Display Name(s)', 'location_display_names'] },
  { name: 'Em_Location_LinkedIn_URLs', aliases: ['Location LinkedIn URL(s)', 'location_linkedin_urls'] },
  { name: 'Em_Location_Non_LinkedIn_URLs', aliases: ['Location non-LinkedIn URL(s)', 'location_non_linkedin_urls'] },
  { name: 'Em_Ultimate_HQ_Names', aliases: ['Ultimate HQ Name(s)', 'ultimate_hq_names'] },
  { name: 'Em_HQ_Names', aliases: ['HQ Name(s)', 'hq_names'] },
  { name: 'Em_Company_LinkedIn_URLs', aliases: ['Company LinkedIn URL(s)', 'company_linkedin_urls'] },
  { name: 'Em_Company_Non_LinkedIn_URLs', aliases: ['Company non-LinkedIn URL(s)', 'company_non_linkedin_urls'] },
  { name: 'Em_Source_File', aliases: ['source_file', 'sourceFile', 'Source File'], computed: 'sourceFile' }
];

let fieldByName = new Map();
let missingCustomFields = [];

if (apiKey) {
  const cfRes = await apiRequest.call(this, {
    method: 'GET',
    baseUrl: apiBaseUrl,
    path: `/locations/${locationId}/customFields?model=contact`,
    headers: authHeaders,
  });
  if (!cfRes.ok) throw new Error(`Failed to fetch contact custom fields: ${cfRes.status} ${JSON.stringify(cfRes.data)}`);
  const customFields = getArrayPayload(cfRes.data);
  fieldByName = new Map(customFields.map((f) => [String(f?.name || '').trim(), f]));
  missingCustomFields = customFieldSpecs.filter((f) => !fieldByName.get(f.name)?.id).map((f) => f.name);
  if (!dryRun && missingCustomFields.length) {
    throw new Error(`Missing required GHL custom fields: ${missingCustomFields.join(', ')}`);
  }
}

const results = [];
for (const rec of records) {
  const sourceFileBase = stripCsvExt(sourceFileOverride || pick(rec, ['Source File', 'source_file', 'sourceFile', 'Batch_Upload', 'batch_upload']));
  const firstName = pick(rec, ['First Name', 'first_name', 'firstName']);
  const lastName = pick(rec, ['Last Name', 'last_name', 'lastName']);
  const email = pick(rec, ['Primary Email', 'primary_email', 'Email', 'email']);
  const phone = pick(rec, ['Primary Phone', 'primary_phone', 'Phone', 'phone']);
  const companyName = pick(rec, ['Company Name(s)', 'company_name', 'companyName']);
  const city = pick(rec, ['Contact City', 'contact_city', 'city']);
  const state = pick(rec, ['Contact State', 'contact_state', 'state']);
  const tags = parseTags(pick(rec, ['Tags', 'tags']), defaultTag, sourceFileBase);

  if (!email && !phone) {
    results.push({ status: 'skipped', reason: 'missing email and phone', firstName, lastName, sourceFile: sourceFileBase || null });
    continue;
  }

  const customValuesByName = {};
  for (const spec of customFieldSpecs) {
    let raw = '';
    if (spec.computed === 'sourceFile') raw = sourceFileBase;
    else raw = pick(rec, spec.aliases);
    if (!raw) continue;
    customValuesByName[spec.name] = raw;
  }

  if (dryRun) {
    results.push({
      status: 'planned',
      email,
      phone,
      firstName,
      lastName,
      companyName,
      sourceFile: sourceFileBase || null,
      tags,
      customFieldsPlanned: Object.keys(customValuesByName),
      standardFieldsPlanned: {
        firstName: !!firstName,
        lastName: !!lastName,
        email: !!email,
        phone: !!phone,
        companyName: !!companyName,
        city: !!city,
        state: !!state,
      },
    });
    continue;
  }

  const upsertBody = {
    locationId,
    firstName: firstName || undefined,
    lastName: lastName || undefined,
    email: email || undefined,
    phone: phone || undefined,
    companyName: companyName || undefined,
    city: city || undefined,
    state: state || undefined,
  };
  Object.keys(upsertBody).forEach((k) => upsertBody[k] === undefined && delete upsertBody[k]);

  const upsertRes = await apiRequest.call(this, {
    method: 'POST',
    baseUrl: apiBaseUrl,
    path: '/contacts/upsert',
    headers: authHeaders,
    body: upsertBody,
  });
  if (!upsertRes.ok) {
    results.push({ status: 'error', step: 'upsert', email, phone, details: upsertRes.data });
    continue;
  }

  const contactId = upsertRes.data?.contact?.id || upsertRes.data?.id || upsertRes.data?.contactId;
  if (!contactId) {
    results.push({ status: 'error', step: 'resolve_contact_id', email, phone, details: upsertRes.data });
    continue;
  }

  const updateEntries = [];
  for (const [name, value] of Object.entries(customValuesByName)) {
    const id = fieldByName.get(name)?.id;
    if (id) updateEntries.push({ id, value });
  }

  if (updateEntries.length) {
    const stampBodies = [
      { locationId, customFields: updateEntries.map((e) => ({ id: e.id, value: e.value })) },
      { customFields: updateEntries.map((e) => ({ id: e.id, value: e.value })) },
      { locationId, customField: Object.fromEntries(updateEntries.map((e) => [e.id, e.value])) },
      { customField: Object.fromEntries(updateEntries.map((e) => [e.id, e.value])) },
    ];

    let stampOk = false;
    let stampErr = null;
    for (const body of stampBodies) {
      const sr = await apiRequest.call(this, {
        method: 'PUT',
        baseUrl: apiBaseUrl,
        path: `/contacts/${contactId}`,
        headers: authHeaders,
        body,
      });
      if (sr.ok) { stampOk = true; break; }
      stampErr = sr;
    }

    if (!stampOk) {
      results.push({ status: 'error', step: 'custom_field_update', contactId, email, details: stampErr?.data || stampErr });
      continue;
    }
  }

  if (tags.length) {
    const tagsResult = await apiRequest.call(this, {
      method: 'POST',
      baseUrl: apiBaseUrl,
      path: `/contacts/${contactId}/tags`,
      headers: authHeaders,
      body: { tags },
    });
    if (!tagsResult.ok) {
      results.push({ status: 'error', step: 'tag_add', contactId, email, tags, details: tagsResult.data });
      continue;
    }
  }

  results.push({ status: 'imported', contactId, email, phone, tagsAdded: tags.length, customFieldsSet: updateEntries.length, sourceFile: sourceFileBase || null });
}

return [{
  json: {
    ok: true,
    dryRun,
    locationId,
    sourceRecords: records.length,
    imported: results.filter((r) => r.status === 'imported').length,
    planned: results.filter((r) => r.status === 'planned').length,
    skipped: results.filter((r) => r.status === 'skipped').length,
    errors: results.filter((r) => r.status === 'error').length,
    missingCustomFields,
    results: results.slice(0, 200),
    note: dryRun ? 'No API writes executed. Provide body.apiKey during dry-run if you want live field validation.' : 'Live run executed.',
  },
}];
